'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { PrimaryButton, SecondaryButton } from '@/components/ui/Button';

const navLinks = [
    { label: 'Home', href: '#hero' },
    { label: 'Services', href: '#services' },
    { label: 'Case Studies', href: '#case-studies' },
    { label: 'About', href: '#about' },
    { label: 'Contact', href: '#cta' },
];

export default function Navbar() {
    const [isScrolled, setIsScrolled] = useState(false);
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    useEffect(() => {
        const handleScroll = () => setIsScrolled(window.scrollY > 20);
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToSection = (href: string) => {
        setIsMobileMenuOpen(false);
        const el = document.querySelector(href);
        if (el) el.scrollIntoView({ behavior: 'smooth' });
    };

    return (
        <>
            <nav
                className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ${isScrolled
                    ? 'h-[70px] bg-[#0A0A0A]/80 backdrop-blur-md shadow-[0_4px_30px_rgba(0,0,0,0.5)] border-b border-white/10'
                    : 'h-[90px] bg-transparent border-b border-transparent'
                    }`}
            >
                <div className="max-w-container h-full flex items-center justify-between">

                    {/* Logo */}
                    <Link href="/" className="flex items-center gap-2 group outline-none">
                        <div className="relative w-10 h-10 overflow-hidden rounded">
                            <Image
                                src="/logo.jpeg"
                                alt="SquadicSolutions Logo"
                                fill
                                className="object-cover brightness-110"
                                priority
                            />
                        </div>
                        <span className="font-extrabold text-2xl text-white tracking-tight">
                            Squadic<span className="text-[#2563EB]">Solutions</span>
                        </span>
                    </Link>

                    {/* Desktop Links */}
                    <div className="hidden md:flex items-center gap-6">
                        <SecondaryButton href="/">Home</SecondaryButton>
                        <SecondaryButton href="/services">Services</SecondaryButton>
                        <SecondaryButton href="/blog">Blog</SecondaryButton>
                        <SecondaryButton href="/about-squadicsolutions">About</SecondaryButton>
                    </div>

                    {/* Right CTA */}
                    <div className="hidden md:block">
                        <PrimaryButton href="/contact">
                            Start a Project
                        </PrimaryButton>
                    </div>

                    {/* Mobile Menu Toggle */}
                    <button
                        onClick={() => setIsMobileMenuOpen(true)}
                        className="md:hidden p-2 text-white hover:text-[#06B6D4] outline-none transition-colors"
                    >
                        <Menu size={28} />
                    </button>
                </div>
            </nav>

            {/* Mobile Menu Overlay */}
            <AnimatePresence>
                {isMobileMenuOpen && (
                    <motion.div
                        className="fixed inset-0 z-[100] bg-[#0A0A0A]/95 backdrop-blur-xl md:hidden flex flex-col"
                        initial={{ opacity: 0, scale: 1.05 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                    >
                        <div className="flex items-center justify-between p-6 border-b border-white/10">
                            <Link href="/" className="flex items-center gap-2" onClick={() => setIsMobileMenuOpen(false)}>
                                <div className="relative w-8 h-8 overflow-hidden rounded">
                                    <Image src="/logo.jpeg" alt="SquadicSolutions Logo" fill className="object-cover" />
                                </div>
                                <span className="font-extrabold text-xl text-white tracking-tight">
                                    Squadic<span className="text-[#2563EB]">Solutions</span>
                                </span>
                            </Link>
                            <button
                                onClick={() => setIsMobileMenuOpen(false)}
                                className="p-2 text-white hover:text-[#06B6D4] bg-white/5 rounded outline-none transition-colors"
                            >
                                <X size={24} />
                            </button>
                        </div>

                        <div className="flex flex-col p-8 gap-8 items-start">
                            <SecondaryButton href="/" onClick={() => setIsMobileMenuOpen(false)} classNameStr="text-2xl">Home</SecondaryButton>
                            <SecondaryButton href="/services" onClick={() => setIsMobileMenuOpen(false)} classNameStr="text-2xl">Services</SecondaryButton>
                            <SecondaryButton href="/blog" onClick={() => setIsMobileMenuOpen(false)} classNameStr="text-2xl">Blog</SecondaryButton>
                            <SecondaryButton href="/about-squadicsolutions" onClick={() => setIsMobileMenuOpen(false)} classNameStr="text-2xl">About</SecondaryButton>
                        </div>

                        <div className="mt-auto p-6 border-t border-white/10 flex justify-center">
                            <PrimaryButton href="/contact" onClick={() => setIsMobileMenuOpen(false)} classNameStr="w-full">
                                Start a Project
                            </PrimaryButton>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
}

'use client';

import { useRef, useMemo } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Float, Edges, Sphere, Line } from '@react-three/drei';
import * as THREE from 'three';

export default function AbstractSStructure() {
    const groupRef = useRef<THREE.Group>(null);
    const { pointer } = useThree();

    // Core Material definitions
    const glassMaterial = useMemo(() => new THREE.MeshPhysicalMaterial({
        color: '#0A192F',
        metalness: 0.9,
        roughness: 0.1,
        transparent: true,
        opacity: 0.8,
        transmission: 0.9,
        clearcoat: 1.0,
        clearcoatRoughness: 0.1,
    }), []);

    // Abstract S Shape Coordinates (roughly forming an S)
    const nodes = useMemo(() => [
        [-2, 3, 0],   // Top Left
        [2, 3, 0],    // Top Right
        [2, 1, 0],    // Right Upper
        [-2, 0, 0],   // Center Left
        [2, -1, 0],   // Center Right
        [-2, -3, 0],  // Bottom Left
        [2, -3, 0],   // Bottom Right
    ], []);

    // Create a smooth curve through the nodes for the main connecting line
    const points = useMemo(() => nodes.map(n => new THREE.Vector3(...n)), [nodes]);
    const curve = useMemo(() => new THREE.CatmullRomCurve3(points, false, 'catmullrom', 0.5), [points]);
    const linePoints = useMemo(() => curve.getPoints(100), [curve]);

    useFrame((state) => {
        if (!groupRef.current) return;

        // Slow continuous rotation
        groupRef.current.rotation.y += 0.002;
        groupRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;

        // Cursor Tilt Interaction (Subtle 3D rotation toward cursor)
        const targetRotationX = (pointer.y * Math.PI) / 8;
        const targetRotationY = (pointer.x * Math.PI) / 8;

        groupRef.current.rotation.x += (targetRotationX - groupRef.current.rotation.x) * 0.05;
        // Don't fully overwrite the automatic Y rotation, just offset it
        groupRef.current.rotation.z += (-targetRotationY - groupRef.current.rotation.z) * 0.05;

        // 12-Second Energy Pulse Effect
        const time = state.clock.elapsedTime;
        const cycle = time % 12; // 12 second loop

        if (cycle < 2) {
            // Pulse active - sweep from top to bottom (y: 4 to -4)
            const pulseY = 4 - (cycle / 2) * 8;

            // Iterate over children to apply glow if they intersect with pulse
            groupRef.current.children.forEach((child) => {
                if (child.type === 'Mesh' && child.position.y > pulseY - 1 && child.position.y < pulseY + 1) {
                    if ((child as THREE.Mesh).material && 'emissiveIntensity' in ((child as THREE.Mesh).material as THREE.MeshStandardMaterial)) {
                        ((child as THREE.Mesh).material as THREE.MeshStandardMaterial).emissiveIntensity = 4;
                    }
                } else if (child.type === 'Mesh' && (child as THREE.Mesh).material && 'emissiveIntensity' in ((child as THREE.Mesh).material as THREE.MeshStandardMaterial)) {
                    // Decay back to normal
                    const mat = ((child as THREE.Mesh).material as THREE.MeshStandardMaterial);
                    mat.emissiveIntensity = THREE.MathUtils.lerp(
                        mat.emissiveIntensity,
                        1,
                        0.1
                    );
                }
            });
        }
    });

    // Pre-calculate randomized values for the floating fragments to avoid "impure function in render" errors
    const floatingFragments = useMemo(() => Array.from({ length: 6 }).map((_, i) => ({
        id: `frag-${i}`,
        position: [
            (Math.random() - 0.5) * 6,
            (Math.random() - 0.5) * 6,
            (Math.random() - 0.5) * 4
        ] as [number, number, number],
        rotation: [Math.random() * Math.PI, Math.random() * Math.PI, 0] as [number, number, number],
        scale: Math.random() * 0.5 + 0.2,
        isWireframe: i % 2 === 0
    })), []);

    // Pre-calculate randomized Z-offsets for structural panels
    const nodeZOffsets = useMemo(() => nodes.map(() => (Math.random() - 0.5) * 1.5), [nodes]);

    return (
        <group ref={groupRef}>
            <Float
                speed={2}
                rotationIntensity={0.5}
                floatIntensity={2}
                floatingRange={[-0.5, 0.5]}
            >
                {/* Connecting Energy Line */}
                <Line
                    points={linePoints}
                    color="#2563EB"
                    lineWidth={3}
                    transparent
                    opacity={0.6}
                />

                {/* Main Geometric Panels forming the S */}
                {nodes.map((pos, i) => (
                    <group key={`node-${i}`} position={new THREE.Vector3(...pos)}>
                        {/* Glowing Node Core */}
                        <Sphere args={[0.15, 16, 16]}>
                            <meshStandardMaterial
                                color={i % 2 === 0 ? "#06B6D4" : "#7C3AED"}
                                emissive={i % 2 === 0 ? "#06B6D4" : "#7C3AED"}
                                emissiveIntensity={2}
                                toneMapped={false}
                            />
                        </Sphere>

                        {/* Floating Structural Panel */}
                        <mesh position={[0, 0, nodeZOffsets[i]]}>
                            <boxGeometry args={[1.5, 0.8, 0.1]} />
                            <primitive object={glassMaterial} attach="material" />
                            {/* Thin neon edge outline */}
                            <Edges
                                linewidth={2}
                                threshold={15}
                                color="#2563EB"
                            />
                        </mesh>
                    </group>
                ))}

                {/* Additional floating architectural fragments to add depth */}
                {floatingFragments.map((frag) => (
                    <mesh
                        key={frag.id}
                        position={frag.position}
                        rotation={frag.rotation}
                        scale={frag.scale}
                    >
                        <boxGeometry args={[1, 1, 1]} />
                        <meshStandardMaterial
                            color="#0A192F"
                            transparent
                            opacity={0.3}
                            wireframe={frag.isWireframe}
                        />
                        {!frag.isWireframe && <Edges linewidth={1} color="#06B6D4" />}
                    </mesh>
                ))}
            </Float>
        </group>
    );
}

'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const metrics = [
    { target: 50, suffix: '+', label: 'Projects Delivered' },
    { target: 99, suffix: '%', label: 'Client Satisfaction' },
    { isText: true, text: 'Scalable', label: 'Architectures' },
    { isText: true, text: 'Enterprise', label: 'Performance' },
];

export default function About() {
    const sectionRef = useRef<HTMLDivElement>(null);
    const particlesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const ctx = gsap.context(() => {
            // Particle floating animation
            gsap.to(".particle", {
                y: "random(-100, 100)",
                x: "random(-100, 100)",
                opacity: "random(0.1, 0.5)",
                duration: "random(3, 6)",
                repeat: -1,
                yoyo: true,
                ease: "sine.inOut",
                stagger: 0.1
            });

            // Count Up & Fade reveal
            const metricItems = gsap.utils.toArray('.metric-item');

            metricItems.forEach((item: any) => {
                const numberEl = item.querySelector('.metric-number');
                const targetVal = parseFloat(numberEl?.getAttribute('data-target') || '0');

                // Reveal container with blur
                gsap.fromTo(item,
                    { opacity: 0, y: 50, filter: 'blur(10px)' },
                    {
                        opacity: 1,
                        y: 0,
                        filter: 'blur(0px)',
                        duration: 1.5,
                        ease: "power3.out",
                        scrollTrigger: {
                            trigger: item,
                            start: "top 85%",
                        }
                    }
                );

                // Run count-up if it's a number
                if (targetVal > 0) {
                    gsap.fromTo(numberEl,
                        { innerText: 0 },
                        {
                            innerText: targetVal,
                            duration: 2.5,
                            ease: "power2.out",
                            snap: { innerText: 1 },
                            scrollTrigger: {
                                trigger: item,
                                start: "top 85%",
                            }
                        }
                    );
                }
            });

        }, sectionRef);

        return () => ctx.revert();
    }, []);

    // Generate static particle divs for the background
    const renderParticles = () => {
        return Array.from({ length: 40 }).map((_, i) => (
            <div
                key={i}
                className="particle absolute rounded-full bg-white opacity-0"
                style={{
                    width: Math.random() * 4 + 1 + 'px',
                    height: Math.random() * 4 + 1 + 'px',
                    top: Math.random() * 100 + '%',
                    left: Math.random() * 100 + '%',
                    boxShadow: '0 0 10px rgba(255,255,255,0.8)'
                }}
            />
        ));
    };

    return (
        <section ref={sectionRef} className="relative min-h-screen py-32 flex items-center bg-[#000000] overflow-hidden" id="about">
            {/* Dark Studio Soft Rim Light */}
            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[80%] h-[30%] bg-[#2563EB] rounded-full blur-[150px] opacity-[0.05] pointer-events-none" />

            {/* Particle Field */}
            <div ref={particlesRef} className="absolute inset-0 pointer-events-none">
                {renderParticles()}
            </div>

            <div className="max-w-container w-full relative z-10">
                <div className="flex flex-col items-center justify-center gap-24">
                    {metrics.map((metric, index) => (
                        <div key={index} className="metric-item flex flex-col items-center justify-center text-center">
                            {metric.isText ? (
                                <span className="text-6xl md:text-8xl lg:text-[120px] font-extrabold text-white tracking-tighter leading-none mb-4 drop-shadow-[0_0_40px_rgba(255,255,255,0.1)]">
                                    {metric.text}
                                </span>
                            ) : (
                                <div className="flex items-baseline text-6xl md:text-8xl lg:text-[120px] font-extrabold text-white tracking-tighter leading-none mb-4 drop-shadow-[0_0_40px_rgba(255,255,255,0.1)]">
                                    <span className="metric-number" data-target={metric.target}>0</span>
                                    <span className="text-[#06B6D4]">{metric.suffix}</span>
                                </div>
                            )}
                            <span className="text-xl md:text-2xl font-bold uppercase tracking-[0.3em] text-[#A1A1AA]">
                                {metric.label}
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
}

'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { SecondaryButton } from '@/components/ui/Button';

gsap.registerPlugin(ScrollTrigger);

const caseStudies = [
    {
        id: '1',
        title: 'FinTech Analytics Engine',
        industry: 'Financial Infrastructure',
        result: 'Sub-millisecond latency on 10M+ daily transactions',
        color: '#2563EB',
    },
    {
        id: '2',
        title: 'Diagnostic Neural Net',
        industry: 'Healthcare AI',
        result: '99.8% precision rate across 50k patient metrics',
        color: '#06B6D4',
    },
    {
        id: '3',
        title: 'Global Supply Chain Router',
        industry: 'Enterprise Logistics',
        result: 'Automated 12,000 daily routes via algorithmic pathing',
        color: '#7C3AED',
    },
    {
        id: '4',
        title: 'ERP Cluster Migration',
        industry: 'Manufacturing Grid',
        result: 'Zero-packet-loss asynchronous database swap',
        color: '#2563EB',
    },
];

export default function CaseStudies() {
    const sectionRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const ctx = gsap.context(() => {
            // Parallax entrance for panels
            const panels = gsap.utils.toArray('.study-panel');

            panels.forEach((panel: any, i) => {
                gsap.fromTo(panel,
                    { opacity: 0, y: 100, rotationX: 15, rotationY: i % 2 === 0 ? 10 : -10, translateZ: -100 },
                    {
                        opacity: 1,
                        y: 0,
                        rotationX: 10,
                        rotationY: i % 2 === 0 ? 5 : -5,
                        translateZ: 0,
                        duration: 1.5,
                        ease: "power3.out",
                        scrollTrigger: {
                            trigger: panel,
                            start: "top 85%",
                        }
                    }
                );
            });

        }, sectionRef);

        return () => ctx.revert();
    }, []);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const x = e.clientX - rect.left; // x position within the element.
        const y = e.clientY - rect.top;  // y position within the element.

        // Calculate rotation based on cursor position (-5 to 5 degrees)
        const xRotation = ((y - rect.height / 2) / rect.height) * -10;
        const yRotation = ((x - rect.width / 2) / rect.width) * 10;

        gsap.to(e.currentTarget, {
            rotationX: xRotation,
            rotationY: yRotation,
            transformPerspective: 1000,
            ease: "power2.out",
            duration: 0.5
        });

        // Move the light reflection
        const reflection = e.currentTarget.querySelector('.reflection');
        if (reflection) {
            gsap.to(reflection, {
                x: x - rect.width / 2,
                y: y - rect.height / 2,
                opacity: 0.8,
                ease: "power2.out",
                duration: 0.2
            });
        }
    };

    const handleMouseLeave = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
        const index = e.currentTarget.getAttribute('data-index');
        const defaultY = Number(index) % 2 === 0 ? 5 : -5;

        gsap.to(e.currentTarget, {
            rotationX: 10,
            rotationY: defaultY,
            transformPerspective: 1000,
            ease: "power3.out",
            duration: 1
        });

        const reflection = e.currentTarget.querySelector('.reflection');
        if (reflection) {
            gsap.to(reflection, {
                opacity: 0,
                ease: "power2.out",
                duration: 0.5
            });
        }
    };

    return (
        <section ref={sectionRef} className="section-padding bg-[#0A0A0A] overflow-hidden" id="case-studies">
            <div className="max-w-container">

                <div className="flex flex-col items-center text-center mb-24">
                    <h2 className="text-5xl md:text-7xl font-extrabold text-white tracking-tight mb-6 drop-shadow-[0_0_20px_rgba(255,255,255,0.1)]">
                        Proven Architectures
                    </h2>
                    <p className="text-xl text-[#A1A1AA] max-w-2xl">
                        Explore instances where our high-performance infrastructure methodologies have radically transformed enterprise outcomes.
                    </p>
                </div>

                {/* 3D Tilted Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24 perspective-[2000px]">
                    {caseStudies.map((study, index) => (
                        <div
                            key={study.id}
                            data-index={index}
                            onMouseMove={handleMouseMove}
                            onMouseLeave={handleMouseLeave}
                            className="study-panel relative w-full aspect-[4/3] rounded border border-white/10 bg-[#000000] cursor-pointer"
                            style={{ transformStyle: 'preserve-3d', boxShadow: `0 20px 50px rgba(0,0,0,0.5), 0 0 20px ${study.color}20` }}
                        >
                            {/* Inner abstract geometric wireframe / texture representing the project */}
                            <div className="absolute inset-0 overflow-hidden rounded opacity-[0.15]">
                                <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
                                    <defs>
                                        <pattern id={`grid-${study.id}`} width="40" height="40" patternUnits="userSpaceOnUse">
                                            <path d="M 40 0 L 0 0 0 40" fill="none" stroke={study.color} strokeWidth="0.5" />
                                        </pattern>
                                    </defs>
                                    <rect width="100%" height="100%" fill={`url(#grid-${study.id})`} />
                                </svg>
                            </div>

                            {/* Volumetric glow based on project category */}
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full blur-[100px] opacity-[0.05] pointer-events-none" style={{ backgroundColor: study.color }} />

                            {/* Cursor Tracker Light Reflection */}
                            <div className="reflection absolute top-1/2 left-1/2 w-[300px] h-[300px] -ml-[150px] -mt-[150px] rounded-full blur-[60px] opacity-0 pointer-events-none mix-blend-screen" style={{ background: `radial-gradient(circle, ${study.color}60 0%, transparent 70%)` }} />

                            {/* Panel Content (Popped out in Z space) */}
                            <div className="absolute inset-x-8 bottom-8 z-10" style={{ transform: 'translateZ(50px)' }}>
                                <span className="text-xs font-bold uppercase tracking-[0.3em] inline-block mb-3" style={{ color: study.color }}>
                                    {study.industry}
                                </span>
                                <h3 className="text-3xl font-extrabold text-white mb-4 leading-tight drop-shadow-[0_2px_10px_rgba(0,0,0,0.8)]">
                                    {study.title}
                                </h3>
                                <div className="h-[1px] w-12 bg-white/20 mb-4" />
                                <p className="text-[#A1A1AA] font-medium drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] mb-6 max-w-sm">
                                    {study.result}
                                </p>

                                <div className="w-12 h-12 rounded-full border border-white/20 flex items-center justify-center pointer-events-none bg-black/50 backdrop-blur-sm">
                                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M5 12h14M12 5l7 7-7 7" />
                                    </svg>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="mt-24 flex justify-center text-center">
                    <SecondaryButton href="/services">View Full Architecture Directory</SecondaryButton>
                </div>

            </div >
        </section >
    );
}

'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const steps = [
    { id: '01', title: 'Architecture Blueprint', desc: 'Deep-system structural analysis and robust cluster mapping.' },
    { id: '02', title: 'Intelligence Integration', desc: 'Embedding neural networks and automated logic pipelines.' },
    { id: '03', title: 'High-Velocity Coding', desc: 'Secure, scalable execution executing strict automated CI/CD.' },
    { id: '04', title: 'Zero-Downtime Deploy', desc: 'Asynchronous release into isolated cloud-native environments.' },
    { id: '05', title: 'Telemetry Scaling', desc: 'Continuous performance optimization and live data monitoring.' },
];

export default function Process() {
    const sectionRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const ctx = gsap.context(() => {
            const tl = gsap.timeline({
                scrollTrigger: {
                    trigger: sectionRef.current,
                    start: "top 70%",
                    end: "bottom 80%",
                    scrub: 1,
                }
            });

            // Draw the SVG glowing line
            tl.fromTo(".process-line path",
                { strokeDasharray: "1000", strokeDashoffset: "1000" },
                { strokeDashoffset: "0", ease: "none", duration: 1 }
            );

            // Pop in the nodes sequentially along the scroll
            const nodes = gsap.utils.toArray('.process-node');
            nodes.forEach((node: any, index) => {
                tl.fromTo(node,
                    { scale: 0, opacity: 0, filter: 'blur(10px)' },
                    {
                        scale: 1,
                        opacity: 1,
                        filter: 'blur(0px)',
                        ease: "back.out(1.7)",
                        duration: 0.2
                    },
                    index * 0.2 // Sequence them along the total duration
                );

                // Add a continuous slow pulse to the node circles after they appear
                gsap.to(node.querySelector('.node-circle'), {
                    boxShadow: "0 0 30px rgba(37,99,235,0.6)",
                    scale: 1.05,
                    duration: 1.5,
                    repeat: -1,
                    yoyo: true,
                    ease: "sine.inOut"
                });
            });

        }, sectionRef);

        return () => ctx.revert();
    }, []);

